<template><el-dialog v-model="open" title="文件夹权限" width="640px" class="folder-permission-dialog"><div class="office-toolbar"><el-select v-model="selected" filterable placeholder="选择成员"><el-option v-for="m in members" :key="m.userId" :label="m.name" :value="String(m.userId)"/></el-select><el-button :disabled="!selected" @click="add">添加授权</el-button></div><div v-for="(r,i) in grants" :key="r.userId" class="grant-row"><strong>{{members.find(m=>String(m.userId)===String(r.userId))?.name||r.userId}}</strong><div class="office-actions"><el-checkbox v-for="op in operations" :key="op.key" v-model="r.permissions[op.key]">{{op.label}}</el-checkbox><el-button circle title="移除此项授权" @click="grants.splice(i,1)"><span class="material-symbols-outlined">close</span></el-button></div></div><el-empty v-if="!grants.length" description="继承上级或团队权限" :image-size="60"/><template #footer><el-button @click="open=false">取消</el-button><el-button type="primary" :loading="saving" @click="save">保存权限</el-button></template></el-dialog></template>
<script setup lang="ts">
import {ref,watch} from 'vue'
import {ElMessage} from 'element-plus'
import request from '@/utils/request'
import {useWorkspaceStore} from '@/stores/workspace'
const props=defineProps<{folderId?:string}>(),open=defineModel<boolean>({default:false}),workspace=useWorkspaceStore(),members=ref<any[]>([]),grants=ref<any[]>([]),selected=ref(''),saving=ref(false),operations=[{key:'view',label:'查看'},{key:'edit',label:'编辑'},{key:'download',label:'下载'},{key:'share',label:'分享'},{key:'delete',label:'删除'}]
watch(open,async show=>{if(!show||!props.folderId)return;try{const b=`/space/${workspace.spaceId}/organization`;const r:any[]=await Promise.all([request.get(b),request.get(b+'/folders/'+props.folderId)]);members.value=r[0].data.members;grants.value=r[1].data.map((x:any)=>({...x,permissions:typeof x.permissions==='string'?JSON.parse(x.permissions):x.permissions}))}catch{open.value=false}})
function add(){if(grants.value.some(g=>String(g.userId)===selected.value))return;grants.value.push({userId:selected.value,permissions:{view:true,edit:false,download:false,share:false,delete:false}});selected.value=''}
async function save(){saving.value=true;try{await request.put(`/space/${workspace.spaceId}/organization/folders/${props.folderId}`,grants.value);open.value=false;ElMessage.success('文件夹权限已保存')}catch{}finally{saving.value=false}}
</script>
<style scoped>.grant-row{display:grid;gap:8px;padding:16px 0;border-bottom:1px solid var(--c-border)}:global(.folder-permission-dialog.el-dialog){max-width:calc(100vw - 24px);max-height:85dvh;overflow:auto}</style>
